--region 丽芙法奥斯生态AI
---@class XCharLifuEcology : XEcologyConstructAIBase
---@field _stateMachine XStateMachineController 状态机
local XCharLifuEcology = XDlcScriptManager.RegCharScript(10606401, "XCharLifuEcology", Base)

--- 注册状态机状态
function XCharLifuEcology:RegisterMachineState()
    self._stateMachine:AddState(StateEnum.TeachingBuilding, XLifuTeachingBuildingState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.Bench, XLifuBenchState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.Auditorium, XLifuAuditoriumState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.InClass, XLifuInClassState.New(self._proxy))
    self._stateMachine:AddState(StateEnum.FindPath, XLifuFindPathState.New(self._proxy))
end

--- 注册状态转移方程
function XCharLifuEcology:RegisterMachineStateTransition()
    -- 设置寻路状态枚举值
    self.FindPathStateEnum = StateEnum.FindPath
    -- 其他状态到寻路状态
    self:RegisterInFindPathStateTransition(StateEnum.TeachingBuilding, function()
        return self._stateMachine:CheckDataBoard(DataBoardKey.TeachingBuilding, 1) and StateEnum.Auditorium or StateEnum.Bench
    end, 5, 1)
    self:RegisterInFindPathStateTransition(StateEnum.Bench, function()
        return self._stateMachine:CheckDataBoard(DataBoardKey.Bench, 1) and StateEnum.Auditorium or StateEnum.InClass
    end, 5, 1)
    self:RegisterInFindPathStateTransition(StateEnum.InClass, function()
        return self._stateMachine:CheckDataBoard(DataBoardKey.InClass, 1) and StateEnum.Auditorium or StateEnum.TeachingBuilding
    end, 5, 1)
    self:RegisterInFindPathStateTransition(StateEnum.Auditorium, function()
        return self._stateMachine:CheckDataBoard(DataBoardKey.Auditorium, 1) and StateEnum.TeachingBuilding or StateEnum.InClass
    end, 5, 1)
    
    -- 寻路状态到其他状态
    self:RegisterOutFindPathStateTransition(StateEnum.TeachingBuilding)
    self:RegisterOutFindPathStateTransition(StateEnum.Bench)
    self:RegisterOutFindPathStateTransition(StateEnum.Auditorium)
    self:RegisterOutFindPathStateTransition(StateEnum.InClass)
end

return XCharLifuEcology
--endregion
